/**
 * Naive O(N²) density computation pass.
 * Computes particle density using Poly6 kernel.
 *
 * @param {*} positionsBuffer Particle positions buffer.
 * @param {*} densitiesBuffer Particle densities buffer.
 * @param {number} particleCount Number of particles.
 * @param {*} poly6Kernel Poly6 kernel coefficient uniform.
 * @param {*} h2 Squared smoothing radius uniform.
 * @param {*} h6 h^6 uniform.
 * @param {*} mass Particle mass uniform.
 * @returns {*} Compute node.
 */
export function computeDensityPass(positionsBuffer: any, densitiesBuffer: any, particleCount: number, poly6Kernel: any, h2: any, h6: any, mass: any): any;
